<script setup lang="ts">
import {useAccountingAlerts} from './useAccountingAlerts';
import {useAccountingLiveRefresh} from './workspaceRealtime';
import {ref,computed,watch} from 'vue';
import AccountingSelect from './AccountingSelect.vue';
import AccountingDocument from './AccountingDocument.vue';
import AdminDialog from '../../AdminDialog.vue';
import {useAccountingPermissions} from './permissions';
import {requestKey} from './requestKey';
const props=defineProps<{company:number;book:any;accounts:any[];csrf?:string;initialFilter?:string;initialFrom?:string;initialTo?:string}>(),emit=defineEmits(['notice']),can=useAccountingPermissions();
const data=ref<any>(null),busy=ref(false),loading=ref(false),error=ref(''),formError=ref(''),editor=ref<any>(null),selected=ref<any>(null),action=ref(''),note=ref(''),date=ref(''),page=ref(1),search=ref(''),direction=ref(''),status=ref('');let generation=0;
const periodFrom=ref(''),periodTo=ref('');
const today=new Date().toLocaleDateString('en-CA');
const bankAccounts=computed(()=>props.accounts.filter(a=>a.active&&!a.is_group&&!a.imprest_fund&&a.account_type==='Bank'&&(!a.currency||a.currency===props.book?.currency)));
const invoiceOptions=computed(()=>data.value?.invoices.filter((i:any)=>(i.currency||props.book?.currency)===props.book?.currency)||[]);
const money=(n:any)=>Number(n||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
async function api(path:string,body?:any){const r=await fetch('/accounting/api/'+path,{method:body?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Unable to complete cheque action.');return d;}
async function load(){const g=++generation;loading.value=true;error.value='';try{const result=await api('cheques?'+new URLSearchParams({company_id:String(props.company),page:String(page.value),search:search.value,direction:direction.value,status:status.value,...(periodFrom.value&&periodTo.value?{from:periodFrom.value,to:periodTo.value}:{})}));if(g===generation)data.value=result;}catch(e){error.value=(e as Error).message;}finally{if(g===generation)loading.value=false;}}
function filter(key:string){direction.value=['issued','received'].includes(key)?key:'';status.value=['issued','received'].includes(key)?'outstanding':['bounced','cleared'].includes(key)?key:'';page.value=1;void load();}
watch(()=>[props.company,props.initialFilter,props.initialFrom,props.initialTo],()=>{editor.value=null;selected.value=null;periodFrom.value=props.initialFrom||'';periodTo.value=props.initialTo||'';filter(props.initialFilter||'');},{immediate:true});
function create(){formError.value='';editor.value={company_id:props.company,request_key:requestKey(),invoice_id:'',bank_account_id:'',cheque_number:'',drawee_bank:'',recorded_date:today,cheque_date:today,amount:'',notes:''};}
async function save(){if(busy.value)return;busy.value=true;formError.value='';try{const r=await api('cheques',editor.value);emit('notice',r.message);editor.value=null;await load();}catch(e){formError.value=(e as Error).message;}finally{busy.value=false;}}
function start(row:any,kind:string){selected.value=row;action.value=kind;date.value=today;note.value='';formError.value='';}
async function run(){if(busy.value)return;busy.value=true;formError.value='';try{const r=await api('cheques/'+selected.value.id+'/actions',{company_id:props.company,version:selected.value.version,action:action.value,date:date.value,note:note.value});emit('notice',r.message);action.value='';selected.value=null;await load();}catch(e){formError.value=(e as Error).message;}finally{busy.value=false;}}
useAccountingLiveRefresh(()=>load(),()=>!editor.value&&!selected.value&&!busy.value);
useAccountingAlerts(error,formError);
</script>
<template><section :class="{'ac-document-open':!!editor}"><div class="ac-section-heading"><div><h2>Cheque Register / PDC</h2><p class="muted">Track received and issued cheques. Pending cheques do not change bank balances.</p></div><button v-if="can('cheques.create')" class="button primary" :disabled="!book||loading||data?.historical" @click="create">+ Register cheque</button></div>
<p v-if="error" class="notice admin-error" role="alert">{{error}}</p><div v-if="data" class="ac-stats ac-overview-stats"><button v-for="key in ['issued','received','bounced','cleared']" :key="key" @click="filter(key)"><small>PDC {{key}}</small><strong>{{data.summary[key].count}}</strong><span>{{book?.currency}} {{money(data.summary[key].amount)}}</span></button></div>
<form class="ac-filters" @submit.prevent="page=1;load()"><label>From<input v-model="periodFrom" type="date" :max="periodTo||today" :required="!!periodTo"></label><label>To<input v-model="periodTo" type="date" :min="periodFrom" :max="today" :required="!!periodFrom"></label><label>Search<input v-model="search" type="search" placeholder="Cheque number or contact"></label><label>Direction<AccountingSelect><select v-model="direction"><option value="">Both directions</option><option value="received">Received</option><option value="issued">Issued</option></select></AccountingSelect></label><label>Status<AccountingSelect><select v-model="status"><option value="">All statuses</option><option v-for="s in ['outstanding','pending','deposited','clearing','cleared','bounced','cancelled']" :key="s" :value="s">{{s==='clearing'?'Awaiting payment approval':s}}</option></select></AccountingSelect></label><button class="button" :disabled="loading">Apply filters</button></form>
<p v-if="data?.historical" class="ac-help">Historical snapshot at {{data.to}}. Actions are disabled; clear the dates to manage current cheques.</p><p v-if="loading" role="status">Loading cheques...</p><div v-else-if="data" class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Cheque / bank</th><th>Contact / invoice</th><th>Direction</th><th>Cheque date</th><th class="numeric">Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="row in data.rows.data" :key="row.id"><td><strong>{{row.cheque_number}}</strong><small>{{row.drawee_bank}}</small></td><td>{{row.party_name}}<small>{{row.invoice_number}}</small></td><td>{{row.direction}}</td><td>{{row.cheque_date}}</td><td class="numeric">{{row.currency}} {{money(row.amount)}}</td><td><span class="ac-badge" :class="row.status==='cleared'?'active':'inactive'">{{row.status==='clearing'?'Awaiting payment approval':row.status}}</span></td><td><div v-if="!data.historical" class="ac-form-actions"><button v-if="row.direction==='received'&&row.status==='pending'&&can('cheques.manage')" class="button" @click="start(row,'deposit')">Deposit</button><button v-if="['pending','deposited'].includes(row.status)&&can('cheques.clear')" class="button" @click="start(row,'clear')">Clear</button><button v-if="['pending','deposited','cleared'].includes(row.status)&&can('cheques.bounce')" class="button" @click="start(row,'bounce')">Bounce</button><button v-if="['pending','deposited','clearing'].includes(row.status)&&can('cheques.manage')" class="button" @click="start(row,'cancel')">Cancel</button></div><details><summary>History</summary><p v-for="event in row.events" :key="event.id">{{event.event_date}} · {{event.action}}<small>{{event.note}}</small></p><p>{{row.notes}}</p></details></td></tr><tr v-if="!data.rows.data.length"><td colspan="7" class="ac-empty-small">No matching cheques.</td></tr></tbody></table></div>
<div v-if="data" class="ac-pagination"><span>Page {{page}} of {{data.rows.last_page}} · {{data.rows.total}} cheques</span><button class="button" :disabled="loading||page<=1" @click="page--;load()">Previous</button><button class="button" :disabled="loading||page>=data.rows.last_page" @click="page++;load()">Next</button></div>
<AccountingDocument v-if="editor" title="Register post-dated cheque" :busy="busy" @close="editor=null"><p class="ac-help">Base currency invoice settlements. Registration does not mark an invoice as paid. Clearance uses the existing payment approval workflow.</p><p v-if="formError" class="notice admin-error" role="alert">{{formError}}</p><form @submit.prevent="save"><fieldset class="ac-journal-fields" :disabled="busy"><div class="ac-form-grid"><label>Posted invoice<AccountingSelect><select v-model.number="editor.invoice_id" required><option value="" disabled>Select invoice</option><option v-for="i in invoiceOptions" :key="i.id" :value="i.id">{{i.number}} — {{i.party_name}} ({{i.kind==='sale'?'Received':'Issued'}})</option></select></AccountingSelect></label><label>Company bank account<AccountingSelect><select v-model.number="editor.bank_account_id" required><option value="" disabled>Select bank</option><option v-for="a in bankAccounts" :key="a.id" :value="a.id">{{a.code}} — {{a.name}}</option></select></AccountingSelect></label><label>Cheque number<input v-model="editor.cheque_number" required maxlength="100"></label><label>Cheque bank name<input v-model="editor.drawee_bank" required maxlength="150" placeholder="Bank printed on cheque"></label><label>Recorded date<input v-model="editor.recorded_date" type="date" required :max="today"></label><label>Cheque date<input v-model="editor.cheque_date" type="date" required :min="editor.recorded_date"></label><label>Amount ({{book?.currency}})<input v-model="editor.amount" required inputmode="decimal" placeholder="0.00" pattern="[0-9]{1,10}(\.[0-9]{1,2})?"></label><label>Notes<textarea v-model="editor.notes" rows="2" maxlength="2000"></textarea></label></div></fieldset><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="editor=null">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Saving...':'Register cheque'}}</button></div></form></AccountingDocument>
<AdminDialog v-if="action" :title="action.charAt(0).toUpperCase()+action.slice(1)+' cheque'" :busy="busy" @close="action=''"><p v-if="formError" class="notice admin-error" role="alert">{{formError}}</p><p>{{selected.cheque_number}} · {{selected.currency}} {{money(selected.amount)}}</p><p v-if="action==='clear'" class="ac-help">Confirm actual bank clearance. Payment approval may be required before the ledger is posted.</p><p v-if="action==='bounce'&&selected.status==='cleared'" class="ac-help">This reverses the cleared payment and restores the invoice outstanding balance.</p><form @submit.prevent="run"><label>Action date<input v-model="date" type="date" required :min="selected.recorded_date" :max="today"></label><label>Reason / bank reference<textarea v-model="note" required minlength="3" maxlength="2000"></textarea></label><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="action=''">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Processing...':'Confirm'}}</button></div></form></AdminDialog>
</section></template>
